<script setup>
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'
const auth=useAuthStore(),router=useRouter(),name=ref(''),email=ref(''),password=ref(''),confirmation=ref(''),error=ref(''),loading=ref(false)
async function submit(){if(password.value!==confirmation.value){error.value='Passwords do not match.';return}loading.value=true;error.value='';try{await auth.register({name:name.value,email:email.value,password:password.value,password_confirmation:confirmation.value});router.push('/suggestions')}catch(e){error.value=e.response?.data?.message??'Unable to create your account.'}finally{loading.value=false}}
</script>
<template><main class="auth-page"><form class="auth-card" @submit.prevent="submit"><p class="eyebrow">FRIDGE → DINNER</p><h1>Create account</h1><label>Name<input v-model="name" data-test="name-input" autocomplete="name" required></label><label>Email<input v-model="email" data-test="email-input" type="email" autocomplete="email" required></label><label>Password<input v-model="password" data-test="password-input" type="password" autocomplete="new-password" required></label><label>Confirm password<input v-model="confirmation" data-test="password-confirm-input" type="password" autocomplete="new-password" required></label><button class="btn btn--tomato" data-test="register-submit" :disabled="loading">Create account</button><p v-if="error" class="error" role="alert">{{ error }}</p><p class="switch">Already registered? <router-link to="/login">Log in</router-link></p></form></main></template>
<style scoped src="../assets/auth.css"></style>
